STYLES_CSS = '/* plan-renderer component styles.\n *\n * Chrome tokens (--bg, --surface, --card, --text, --muted, --accent, …)\n * come from the active palette (default: black-silver). Status tokens\n * (--st-*) are declared inline below so every distinct phase lifecycle,\n * item state, sub-state, and activity role gets its own semantic colour\n * – the renderer needs more than the usual RAG palette.\n *\n * Light is the default. Dark mode kicks in on [data-omnis-mode="dark"]\n * on <html>. */\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;\n  font-size: 16px;\n  line-height: 1.5;\n}\n\n::selection { background: var(--selection-bg); }\n:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }\n\na { color: var(--accent); }\ncode { background: var(--surface); padding: 0 .25em; border-radius: 3px; }\n\n/* ─── Semantic status palette (light) ───────────────────────────\n *\n * Each named state has three rgba variants: solid text colour, soft\n * background, and ~30% border. Every distinct state gets its own hue\n * so the user never has to disambiguate "which kind of done is this"\n * from context alone. The only deliberate aliases are:\n *   – pending == idle (semantically identical: "not started")\n *   – blocked is one colour across all three layers (a phase, item\n *     or sub-state is blocked is blocked) */\n\n:root {\n  /* pending / idle – slate */\n  --st-pending:           #64748B;\n  --st-pending-bg:        rgba(100,116,139,0.10);\n  --st-pending-border:    rgba(100,116,139,0.32);\n\n  /* current (phase lifecycle: this phase is live) – sky */\n  --st-current:           #0284C7;\n  --st-current-bg:        rgba(2,132,199,0.10);\n  --st-current-border:    rgba(2,132,199,0.32);\n\n  /* in-progress (item: this bullet is being worked on) – amber */\n  --st-in-progress:       #D97706;\n  --st-in-progress-bg:    rgba(217,119,6,0.10);\n  --st-in-progress-border:rgba(217,119,6,0.32);\n\n  /* done (item: bullet finished on disk, pre-review) – emerald */\n  --st-done:              #10B981;\n  --st-done-bg:           rgba(16,185,129,0.10);\n  --st-done-border:       rgba(16,185,129,0.32);\n\n  /* ready (sub-state: inner-review loop is clean, awaiting outer\n     review) – lime; sits between done (item) and completed (lifecycle) */\n  --st-ready:             #65A30D;\n  --st-ready-bg:          rgba(101,163,13,0.10);\n  --st-ready-border:      rgba(101,163,13,0.32);\n\n  /* completed (phase lifecycle: outer reviewer signed off, terminal) –\n     deep emerald, darker than item done for terminal weight */\n  --st-completed:         #047857;\n  --st-completed-bg:      rgba(4,120,87,0.12);\n  --st-completed-border:  rgba(4,120,87,0.40);\n\n  /* blocked (any layer) – crimson */\n  --st-blocked:           #DC2626;\n  --st-blocked-bg:        rgba(220,38,38,0.12);\n  --st-blocked-border:    rgba(220,38,38,0.35);\n\n  /* under-review (phase lifecycle: outer reviewer running) – indigo */\n  --st-under-review:      #4F46E5;\n  --st-under-review-bg:   rgba(79,70,229,0.10);\n  --st-under-review-border:rgba(79,70,229,0.32);\n\n  /* inner-review (sub-state: review-iterate running) – violet,\n     intentionally distinct from under-review indigo */\n  --st-inner-review:      #7C3AED;\n  --st-inner-review-bg:   rgba(124,58,237,0.10);\n  --st-inner-review-border:rgba(124,58,237,0.32);\n\n  /* needs-fixes (phase lifecycle: outer review left findings) – orange */\n  --st-needs-fixes:       #EA580C;\n  --st-needs-fixes-bg:    rgba(234,88,12,0.10);\n  --st-needs-fixes-border:rgba(234,88,12,0.32);\n\n  /* applying-fixes (sub-state: implementer is consuming inner-review\n     findings) – magenta, intentionally distinct from needs-fixes orange */\n  --st-applying-fixes:    #DB2777;\n  --st-applying-fixes-bg: rgba(219,39,119,0.10);\n  --st-applying-fixes-border:rgba(219,39,119,0.32);\n\n  /* coding (sub-state: implementer writing code) – teal */\n  --st-coding:            #0D9488;\n  --st-coding-bg:         rgba(13,148,136,0.10);\n  --st-coding-border:     rgba(13,148,136,0.32);\n\n  /* activity roles */\n  --st-implementer:       #0D9488;   /* teal, matches coding */\n  --st-reviewer:          #1E40AF;   /* navy, distinct from current sky */\n}\n\n/* Dark-mode overrides – brighter, lower-saturation pastel variants so\n   text reads cleanly against #0A0A0C. */\n[data-omnis-mode="dark"] {\n  --st-pending:           #94A3B8;\n  --st-pending-bg:        rgba(148,163,184,0.14);\n  --st-pending-border:    rgba(148,163,184,0.30);\n\n  --st-current:           #38BDF8;\n  --st-current-bg:        rgba(56,189,248,0.14);\n  --st-current-border:    rgba(56,189,248,0.30);\n\n  --st-in-progress:       #FBBF24;\n  --st-in-progress-bg:    rgba(251,191,36,0.14);\n  --st-in-progress-border:rgba(251,191,36,0.30);\n\n  --st-done:              #34D399;\n  --st-done-bg:           rgba(52,211,153,0.14);\n  --st-done-border:       rgba(52,211,153,0.30);\n\n  --st-ready:             #A3E635;\n  --st-ready-bg:          rgba(163,230,53,0.14);\n  --st-ready-border:      rgba(163,230,53,0.32);\n\n  --st-completed:         #059669;\n  --st-completed-bg:      rgba(5,150,105,0.18);\n  --st-completed-border:  rgba(5,150,105,0.42);\n\n  --st-blocked:           #FB7185;\n  --st-blocked-bg:        rgba(251,113,133,0.16);\n  --st-blocked-border:    rgba(251,113,133,0.35);\n\n  --st-under-review:      #818CF8;\n  --st-under-review-bg:   rgba(129,140,248,0.14);\n  --st-under-review-border:rgba(129,140,248,0.30);\n\n  --st-inner-review:      #C4B5FD;\n  --st-inner-review-bg:   rgba(196,181,253,0.14);\n  --st-inner-review-border:rgba(196,181,253,0.30);\n\n  --st-needs-fixes:       #FB923C;\n  --st-needs-fixes-bg:    rgba(251,146,60,0.14);\n  --st-needs-fixes-border:rgba(251,146,60,0.30);\n\n  --st-applying-fixes:    #F472B6;\n  --st-applying-fixes-bg: rgba(244,114,182,0.14);\n  --st-applying-fixes-border:rgba(244,114,182,0.32);\n\n  --st-coding:            #5EEAD4;\n  --st-coding-bg:         rgba(94,234,212,0.13);\n  --st-coding-border:     rgba(94,234,212,0.30);\n\n  --st-implementer:       #5EEAD4;\n  --st-reviewer:          #60A5FA;\n}\n\n/* ─── App chrome ──────────────────────────────────────────────── */\n\n/* The bar pins to the top of the viewport so the legend is always\n   in view while the user scrolls through phases. Box-shadow gives a\n   subtle separation when content scrolls under it. */\n.app-bar {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 10px 24px 8px;\n  background: var(--sidebar);\n  color: var(--on-sidebar);\n  border-bottom: 1px solid var(--border);\n  box-shadow: var(--shadow-soft);\n}\n.app-bar-top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n.app-bar .app-title {\n  font-weight: 600;\n  font-size: 18px;\n  letter-spacing: .02em;\n  color: var(--on-sidebar-active);\n}\n.app-bar .controls { display: flex; gap: 8px; }\n\n/* Legend – three rows (Phase / Item / Live), each a wrapping flex\n   of `swatch + label` pills. Stays inside .app-bar so it scrolls\n   with the title bar (i.e. it\'s always visible). */\n.legend {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  font-size: 13px;\n  line-height: 1.4;\n}\n.legend-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 4px 10px;\n}\n.legend-row-label {\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: .08em;\n  font-weight: 600;\n  color: var(--on-sidebar);\n  min-width: 42px;\n}\n.legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  color: var(--on-sidebar);\n  white-space: nowrap;\n}\n.legend-swatch {\n  width: 9px;\n  height: 9px;\n  border-radius: 50%;\n  display: inline-block;\n  flex-shrink: 0;\n  border: 1px solid rgba(255,255,255,0.08);\n}\n.legend-swatch.completed {\n  /* terminal lifecycle state gets a thicker ring so it visually reads\n     as "sealed" vs the lighter item-done dot */\n  box-shadow: 0 0 0 1.5px var(--st-completed-border) inset;\n}\n\n.legend-swatch.pending        { background: var(--st-pending); }\n.legend-swatch.current        { background: var(--st-current); }\n.legend-swatch.in-progress    { background: var(--st-in-progress); }\n.legend-swatch.done           { background: var(--st-done); }\n.legend-swatch.ready          { background: var(--st-ready); }\n.legend-swatch.completed      { background: var(--st-completed); }\n.legend-swatch.blocked        { background: var(--st-blocked); }\n.legend-swatch.under-review   { background: var(--st-under-review); }\n.legend-swatch.inner-review   { background: var(--st-inner-review); }\n.legend-swatch.needs-fixes    { background: var(--st-needs-fixes); }\n.legend-swatch.applying-fixes { background: var(--st-applying-fixes); }\n.legend-swatch.coding         { background: var(--st-coding); }\n.legend-swatch.idle           { background: var(--st-pending); }\n\nmain {\n  padding: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n/* ─── Cards ───────────────────────────────────────────────────── */\n\n.card {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 16px 20px;\n  box-shadow: var(--shadow-soft);\n}\n.card h2 {\n  margin: 0 0 12px;\n  font-size: 17px;\n  font-weight: 600;\n  letter-spacing: .02em;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--text);\n}\n\n.plan-header { padding: 16px 20px; }\n.plan-intro {\n  margin: 0;\n  color: var(--muted);\n  font-size: 15px;\n}\n.phase-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 12px;\n}\n\n.card-flow { padding: 12px 16px; }\n.card-flow pre.mermaid,\n.card-flow .mermaid-rendered {\n  background: var(--surface);\n  border-radius: 6px;\n  padding: 12px;\n  overflow-x: auto;\n  display: flex;\n  justify-content: center;\n}\n.mermaid-rendered svg { max-width: 100%; height: auto; }\n\n/* ── Mermaid node theming ─────────────────────────────────────── */\n/* Phase Flow nodes share the lifecycle palette. Defaults to pending;\n   class overrides target done/completed, current/inProgress/active,\n   blocked, needsFixes, underReview. !important beats the inline\n   fill="…" mermaid emits for classDef hex colours. */\n\n.mermaid-rendered g.node > rect,\n.mermaid-rendered g.node > polygon,\n.mermaid-rendered g.node > path,\n.mermaid-rendered g.node > circle,\n.mermaid-rendered g.node > ellipse {\n  fill: var(--st-pending) !important;\n  stroke: var(--st-pending) !important;\n}\n.mermaid-rendered g.node .nodeLabel,\n.mermaid-rendered g.node .nodeLabel > p,\n.mermaid-rendered g.node foreignObject span,\n.mermaid-rendered g.node foreignObject p {\n  color: #FFFFFF !important;\n  fill: #FFFFFF !important;\n}\n\n/* Phase-level completion in Mermaid uses the deep terminal emerald.\n   `done` is a legacy alias for `completed` at the phase level – Mermaid\n   nodes don\'t represent items, so this is the lifecycle colour. */\n.mermaid-rendered g.node.done > rect,\n.mermaid-rendered g.node.completed > rect,\n.mermaid-rendered g.node.done > polygon,\n.mermaid-rendered g.node.completed > polygon,\n.mermaid-rendered g.node.done > path,\n.mermaid-rendered g.node.completed > path,\n.mermaid-rendered g.node.done > circle,\n.mermaid-rendered g.node.completed > circle,\n.mermaid-rendered g.node.done > ellipse,\n.mermaid-rendered g.node.completed > ellipse {\n  fill: var(--st-completed) !important;\n  stroke: var(--st-completed) !important;\n}\n\n.mermaid-rendered g.node.current > rect,\n.mermaid-rendered g.node.inProgress > rect,\n.mermaid-rendered g.node.active > rect,\n.mermaid-rendered g.node.current > polygon,\n.mermaid-rendered g.node.inProgress > polygon,\n.mermaid-rendered g.node.active > polygon,\n.mermaid-rendered g.node.current > path,\n.mermaid-rendered g.node.inProgress > path,\n.mermaid-rendered g.node.active > path,\n.mermaid-rendered g.node.current > circle,\n.mermaid-rendered g.node.inProgress > circle,\n.mermaid-rendered g.node.active > circle,\n.mermaid-rendered g.node.current > ellipse,\n.mermaid-rendered g.node.inProgress > ellipse,\n.mermaid-rendered g.node.active > ellipse {\n  fill: var(--st-current) !important;\n  stroke: var(--st-current) !important;\n}\n\n.mermaid-rendered g.node.blocked > rect,\n.mermaid-rendered g.node.blocked > polygon,\n.mermaid-rendered g.node.blocked > path,\n.mermaid-rendered g.node.blocked > circle,\n.mermaid-rendered g.node.blocked > ellipse {\n  fill: var(--st-blocked) !important;\n  stroke: var(--st-blocked) !important;\n}\n\n.mermaid-rendered g.node.needsFixes > rect,\n.mermaid-rendered g.node.needsFixes > polygon,\n.mermaid-rendered g.node.needsFixes > path,\n.mermaid-rendered g.node.needsFixes > circle,\n.mermaid-rendered g.node.needsFixes > ellipse {\n  fill: var(--st-needs-fixes) !important;\n  stroke: var(--st-needs-fixes) !important;\n}\n\n.mermaid-rendered g.node.underReview > rect,\n.mermaid-rendered g.node.underReview > polygon,\n.mermaid-rendered g.node.underReview > path,\n.mermaid-rendered g.node.underReview > circle,\n.mermaid-rendered g.node.underReview > ellipse {\n  fill: var(--st-under-review) !important;\n  stroke: var(--st-under-review) !important;\n}\n\n.mermaid-rendered .edgePath .path,\n.mermaid-rendered .flowchart-link {\n  stroke: var(--border-strong) !important;\n}\n.mermaid-rendered .arrowheadPath,\n.mermaid-rendered marker path {\n  fill: var(--border-strong) !important;\n  stroke: var(--border-strong) !important;\n}\n.mermaid-rendered .edgeLabel {\n  background-color: var(--surface) !important;\n  color: var(--muted) !important;\n}\n\n/* ─── Status chips (phase lifecycle + item state) ─────────────── */\n\n.chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 2px 10px;\n  border-radius: 999px;\n  font-size: 14px;\n  font-weight: 500;\n  border: 1px solid transparent;\n  background: var(--st-pending-bg);\n  color: var(--st-pending);\n  border-color: var(--st-pending-border);\n  text-transform: lowercase;\n  letter-spacing: .02em;\n}\n.chip-dot {\n  width: 8px; height: 8px;\n  border-radius: 50%;\n  background: currentColor;\n}\n.chip-tiny {\n  padding: 0 8px;\n  font-size: 13px;\n  height: 18px;\n  line-height: 18px;\n}\n\n/* lifecycle */\n.chip-pending      { color: var(--st-pending);        background: var(--st-pending-bg);        border-color: var(--st-pending-border); }\n.chip-current      { color: var(--st-current);        background: var(--st-current-bg);        border-color: var(--st-current-border); }\n.chip-under-review { color: var(--st-under-review);   background: var(--st-under-review-bg);   border-color: var(--st-under-review-border); }\n.chip-needs-fixes  { color: var(--st-needs-fixes);    background: var(--st-needs-fixes-bg);    border-color: var(--st-needs-fixes-border); }\n.chip-completed    { color: var(--st-completed);      background: var(--st-completed-bg);      border-color: var(--st-completed-border); }\n.chip-blocked      { color: var(--st-blocked);        background: var(--st-blocked-bg);        border-color: var(--st-blocked-border); }\n\n/* item state */\n.chip-in-progress  { color: var(--st-in-progress);    background: var(--st-in-progress-bg);    border-color: var(--st-in-progress-border); }\n.chip-done         { color: var(--st-done);           background: var(--st-done-bg);           border-color: var(--st-done-border); }\n\n/* sub-state */\n.chip-idle           { color: var(--st-pending);        background: var(--st-pending-bg);        border-color: var(--st-pending-border); }\n.chip-coding         { color: var(--st-coding);         background: var(--st-coding-bg);         border-color: var(--st-coding-border); }\n.chip-inner-review   { color: var(--st-inner-review);   background: var(--st-inner-review-bg);   border-color: var(--st-inner-review-border); }\n.chip-applying-fixes { color: var(--st-applying-fixes); background: var(--st-applying-fixes-bg); border-color: var(--st-applying-fixes-border); }\n.chip-ready          { color: var(--st-ready);          background: var(--st-ready-bg);          border-color: var(--st-ready-border); }\n\n/* ─── Phase cards ─────────────────────────────────────────────── */\n\n.phases { display: flex; flex-direction: column; gap: 12px; }\n\n.phase {\n  padding: 0;\n  overflow: hidden;\n  border-left: 3px solid var(--border-strong);\n}\n.phase-pending      { border-left-color: var(--st-pending-border); }\n.phase-current      { border-left-color: var(--st-current-border); }\n.phase-under-review { border-left-color: var(--st-under-review-border); }\n.phase-needs-fixes  { border-left-color: var(--st-needs-fixes-border); }\n.phase-completed    { border-left-color: var(--st-completed-border); }\n.phase-blocked      { border-left-color: var(--st-blocked-border); }\n\n.phase-head {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 14px 20px;\n  cursor: pointer;\n  user-select: none;\n}\n.phase-head:hover { background: var(--surface); }\n.phase-num {\n  font-family: ui-monospace, monospace;\n  font-size: 14px;\n  color: var(--muted);\n  letter-spacing: .04em;\n}\n.phase-title {\n  flex: 1;\n  font-weight: 500;\n  font-size: 16px;\n  color: var(--text);\n}\n\n.phase-body {\n  padding: 0 20px 20px;\n  border-top: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n.phase.collapsed .phase-body { display: none; }\n.phase.collapsed .phase-head { border-top: none; }\n\n.phase-intro {\n  margin: 12px 0 0;\n  color: var(--muted);\n  font-size: 15px;\n}\n.phase-intro-block {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.phase-intro-block pre.mermaid,\n.phase-intro-block .mermaid-rendered {\n  background: var(--surface);\n  border-radius: 6px;\n  padding: 12px;\n  overflow-x: auto;\n  display: flex;\n  justify-content: center;\n}\n.phase-intro-block pre.code-block {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 10px 12px;\n  overflow-x: auto;\n  font-size: 14px;\n  font-family: ui-monospace, monospace;\n  margin: 0;\n}\n.phase-intro-block pre.code-block code { background: transparent; padding: 0; }\n\n.phase-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n}\n@media (max-width: 720px) {\n  .phase-grid { grid-template-columns: 1fr; }\n}\n\n/* ─── Items (Work / Files / Acceptance) ───────────────────────── */\n\n.items-label {\n  margin: 0 0 6px;\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: .06em;\n  text-transform: uppercase;\n  color: var(--muted);\n}\n.items-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.items-empty {\n  margin: 0;\n  color: var(--dim);\n  font-size: 15px;\n}\n\n.item {\n  display: grid;\n  grid-template-columns: 32px 1fr auto;\n  grid-template-areas:\n    "id   text chip"\n    ".    note note";\n  align-items: start;\n  gap: 2px 8px;\n  padding: 6px 8px;\n  border-radius: 4px;\n}\n.item:hover { background: var(--surface); }\n.item-id { grid-area: id; }\n.item-text { grid-area: text; }\n.item-note { grid-area: note; }\n.item > .chip {\n  grid-area: chip;\n  align-self: start;\n  white-space: nowrap;\n}\n\n.item-id {\n  font-family: ui-monospace, monospace;\n  font-size: 13px;\n  color: var(--muted);\n  padding-top: 2px;\n}\n.item-text {\n  font-size: 15px;\n  color: var(--text);\n}\n.item-completed .item-text { color: var(--muted); }\n.item-note {\n  display: block;\n  font-size: 13px;\n  color: var(--accent);\n  margin-top: 2px;\n  font-style: italic;\n}\n\n/* ─── Live panel (in-current-phase only) ──────────────────────── */\n/* Border tint follows the active sub-state; the label and substate\n   text use the same colour so the panel re-keys itself on every\n   sub-state flip. */\n\n.live-panel {\n  margin-top: 16px;\n  background: var(--surface);\n  border: 1px solid var(--st-coding-border);\n  border-left-width: 3px;\n  border-radius: 6px;\n  padding: 12px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.live-panel.live-sub-idle           { border-color: var(--st-pending-border);        border-left-color: var(--st-pending); }\n.live-panel.live-sub-coding         { border-color: var(--st-coding-border);         border-left-color: var(--st-coding); }\n.live-panel.live-sub-inner-review   { border-color: var(--st-inner-review-border);   border-left-color: var(--st-inner-review); }\n.live-panel.live-sub-applying-fixes { border-color: var(--st-applying-fixes-border); border-left-color: var(--st-applying-fixes); }\n.live-panel.live-sub-ready          { border-color: var(--st-ready-border);          border-left-color: var(--st-ready); }\n.live-panel.live-sub-blocked        { border-color: var(--st-blocked-border);        border-left-color: var(--st-blocked); }\n\n.live-head {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.live-label {\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-transform: uppercase;\n  color: var(--st-coding);\n}\n.live-panel.live-sub-idle           .live-label { color: var(--st-pending); }\n.live-panel.live-sub-coding         .live-label { color: var(--st-coding); }\n.live-panel.live-sub-inner-review   .live-label { color: var(--st-inner-review); }\n.live-panel.live-sub-applying-fixes .live-label { color: var(--st-applying-fixes); }\n.live-panel.live-sub-ready          .live-label { color: var(--st-ready); }\n.live-panel.live-sub-blocked        .live-label { color: var(--st-blocked); }\n\n.live-sub {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 16px;\n  font-size: 14px;\n}\n.live-meta { display: inline-flex; align-items: baseline; gap: 6px; }\n.live-meta-k {\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--dim);\n}\n.live-substate {\n  font-weight: 600;\n  font-family: ui-monospace, monospace;\n  color: var(--st-coding);\n}\n.live-substate.sub-idle           { color: var(--st-pending); }\n.live-substate.sub-coding         { color: var(--st-coding); }\n.live-substate.sub-inner-review   { color: var(--st-inner-review); }\n.live-substate.sub-applying-fixes { color: var(--st-applying-fixes); }\n.live-substate.sub-ready          { color: var(--st-ready); }\n.live-substate.sub-blocked        { color: var(--st-blocked); }\n\n/* Cycle counter – distinct visual emphasis so the user sees it tick. */\n.live-cycle {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 4px;\n  font-family: ui-monospace, monospace;\n}\n.live-cycle-k { font-weight: 700; color: var(--st-inner-review); }\n.live-cycle-cap { color: var(--muted); }\n\n.activity-log {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-family: ui-monospace, monospace;\n  font-size: 13.5px;\n  max-height: 220px;\n  overflow-y: auto;\n}\n.activity {\n  display: grid;\n  grid-template-columns: 50px 110px 1fr;\n  gap: 8px;\n  padding: 3px 0;\n  border-bottom: 1px dashed var(--border);\n}\n.activity:last-child { border-bottom: none; }\n.activity-time { color: var(--dim); }\n.activity-role {\n  font-weight: 600;\n  letter-spacing: .02em;\n  text-transform: lowercase;\n}\n.activity-implementer  .activity-role { color: var(--st-implementer); }\n.activity-inner-review .activity-role { color: var(--st-inner-review); }\n.activity-reviewer     .activity-role { color: var(--st-reviewer); }\n.activity-msg { color: var(--text); }\n\n/* Proposed decisions */\n.proposed-decisions {\n  border-top: 1px solid var(--border);\n  padding-top: 10px;\n  margin-top: 4px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.proposed-label {\n  font-size: 13px;\n  letter-spacing: .04em;\n  color: var(--muted);\n}\n.proposed-card {\n  background: var(--card);\n  border: 1px dashed var(--accent);\n  border-radius: 4px;\n  padding: 8px 12px;\n}\n.proposed-text { margin: 0 0 4px; font-size: 15px; }\n.proposed-just { margin: 0; font-size: 13.5px; color: var(--muted); font-style: italic; }\n\n/* ─── Decisions cards ─────────────────────────────────────────── */\n\n.decisions-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\n  gap: 10px;\n}\n.decision-card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 10px 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n.decision-title {\n  font-weight: 600;\n  font-size: 15px;\n  color: var(--text);\n}\n.decision-body {\n  margin: 0;\n  font-size: 14px;\n  color: var(--muted);\n  line-height: 1.45;\n}\n.decisions-tools {\n  margin-top: 12px;\n  display: flex;\n  gap: 8px;\n}\n\n/* ─── Footer (open Q + risks) ─────────────────────────────────── */\n\n.footer-sections {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n}\n@media (max-width: 720px) {\n  .footer-sections { grid-template-columns: 1fr; }\n}\n.card-half h2 { margin-bottom: 8px; }\n.card-half ul { margin: 0 0 12px 18px; padding: 0; }\n.card-half li { font-size: 15px; margin-bottom: 4px; }\n.muted { color: var(--muted); font-style: italic; font-size: 15px; }\n\n/* ─── Buttons ─────────────────────────────────────────────────── */\n\n.btn {\n  appearance: none;\n  background: var(--accent);\n  color: var(--on-accent);\n  border: 1px solid var(--accent);\n  padding: 4px 10px;\n  font-size: 14px;\n  border-radius: 4px;\n  cursor: pointer;\n  letter-spacing: .02em;\n  font-weight: 500;\n}\n.btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }\n.btn-ghost {\n  background: transparent;\n  color: var(--accent);\n  border-color: var(--border-strong);\n}\n.btn-ghost:hover {\n  background: var(--accent-bg);\n  border-color: var(--accent);\n}\n.actions { display: flex; gap: 6px; flex-wrap: wrap; }\n.phase-actions {\n  display: flex;\n  gap: 6px;\n  flex-wrap: wrap;\n  border-top: 1px solid var(--border);\n  padding-top: 12px;\n}\n\n.badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 1px 8px;\n  border-radius: 999px;\n  font-size: 13px;\n  font-weight: 600;\n  letter-spacing: .02em;\n}\n.badge-attention {\n  background: var(--st-needs-fixes-bg);\n  color: var(--st-needs-fixes);\n  border: 1px solid var(--st-needs-fixes-border);\n}\n\n/* ─── Toast (prompt emit feedback) ────────────────────────────── */\n\n.toast {\n  position: fixed;\n  bottom: 20px;\n  right: 20px;\n  max-width: 480px;\n  background: var(--card);\n  border: 1px solid var(--st-current-border);\n  border-radius: 8px;\n  padding: 14px 16px;\n  box-shadow: var(--shadow-overlay);\n  z-index: 1000;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  transition: opacity .4s ease, transform .4s ease;\n}\n.toast-fade { opacity: 0; transform: translateY(8px); }\n.toast-label {\n  font-size: 13px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--st-current);\n  font-weight: 600;\n}\n.toast-prompt {\n  margin: 0;\n  padding: 8px 10px;\n  background: var(--surface);\n  border-radius: 4px;\n  font-size: 14px;\n  font-family: ui-monospace, monospace;\n  white-space: pre-wrap;\n  max-height: 160px;\n  overflow-y: auto;\n  color: var(--text);\n}\n.toast-close { align-self: flex-end; }\n\n/* ─── Scrollbar ───────────────────────────────────────────────── */\n\n* { scrollbar-width: thin; scrollbar-color: var(--scrollbar-thumb) transparent; }\n*::-webkit-scrollbar { width: 8px; height: 8px; }\n*::-webkit-scrollbar-thumb { background: var(--scrollbar-thumb); border-radius: 4px; }\n*::-webkit-scrollbar-track { background: transparent; }\n'
